package com.projectdark.mobile;
import static org.junit.Assert.*;
import android.content.*;import android.graphics.*;import com.projectdark.mobile.world.*;import java.util.*;import java.lang.reflect.*;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class TownServicesV247Test {
 Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("project_dark_f5m_v1",0).edit().clear().commit();F5mSaveStore.install(c);}
 static List<TownInteriorDef> rooms(){List<TownInteriorDef> a=new ArrayList<>();a.addAll(TownInteriorDef.ALL);a.addAll(TownInteriorDef.ABEL);a.addAll(TownInteriorDef.RUCESION);a.addAll(TownInteriorDef.MINE);return a;}
 void shot(GameView v,String name)throws Exception{Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));save(b,name);b.recycle();}
 static void save(Bitmap b,String name)throws Exception{File f=new File("build/reports/horror-v179/v247/"+name+".png");f.getParentFile().mkdirs();try(FileOutputStream o=new FileOutputStream(f)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,o));}}
 static int[] px(Bitmap b){int[] a=new int[b.getWidth()*b.getHeight()];b.getPixels(a,0,b.getWidth(),0,0,b.getWidth(),b.getHeight());return a;}
 void tap(TownShopWindow w,float x,float y,TownCommerce.Durability d){assertTrue(w.touch(120+x*1.125f,y*1.125f,0,d));}
 @Test public void everyServiceRoleUsesExactOriginalSpriteAndMillesQuestsRemainReachable()throws Exception{
  NpcActorRenderer actor=new NpcActorRenderer(c);Set<String> roles=new HashSet<>();int count=0;
  for(TownInteriorDef d:rooms()){String role=TownServiceArt.role(d.npcId);if(d.kind!=TownInteriorDef.Kind.INN&&d.kind!=TownInteriorDef.Kind.EQUIPMENT)continue;roles.add(role);count++;Bitmap actual=Bitmap.createBitmap(128,128,Bitmap.Config.ARGB_8888);actor.draw(new Canvas(actual),d.npcId,64,112,CharacterRenderer.Direction.NE,CharacterRenderer.State.WALK,99);Bitmap source;try(InputStream in=c.getAssets().open("town-v247/"+role+".png")){source=BitmapFactory.decodeStream(in);}Bitmap expect=Bitmap.createBitmap(128,128,Bitmap.Config.ARGB_8888);new Canvas(expect).drawBitmap(source,64-source.getWidth()/2f,112-source.getHeight(),new Paint());assertArrayEquals(d.mapId,px(expect),px(actual));save(actual,d.mapId+"-source-actor");actual.recycle();expect.recycle();source.recycle();}
  assertEquals(9,count);assertEquals(new HashSet<>(Arrays.asList("inn","equipment")),roles);TownServiceArt.register("future_keeper_777","INN");TownServiceArt.register("future_keeper_778","EQUIPMENT");assertEquals("inn",TownServiceArt.role("future_keeper_777"));assertEquals("equipment",TownServiceArt.role("future_keeper_778"));
  RuntimeState s=new RuntimeState();Set<String> ids=new HashSet<>();for(RuntimeState.Npc n:s.npcs())ids.add(n.id);assertEquals(4,ids.size());for(String job:CampaignProgress.JOBS){assertFalse(ids.contains(CampaignProgress.mentor(job)));for(int tier=1;tier<=2;tier++){CampaignProgress.Def d=CampaignProgress.find("J0"+tier+"_"+job);assertEquals("milles_job_counselor",d.npc);assertTrue(ids.contains(d.npc));}assertEquals(CampaignProgress.mentor(job),CampaignProgress.find("J03_"+job).npc);}
  for(CampaignProgress.Def d:CampaignProgress.definitions())if(WorldDef.ID.equals(d.map)&&!d.kind.equals("EXTERNAL"))assertTrue(d.id+" NPC reachable",ids.contains(d.npc));
 }
 @Test public void allNineteenServicesOpenActualScenesAndNineShopsTradeThroughSharedOriginalUi()throws Exception{
  int retail=0;for(TownInteriorDef d:rooms()){
   c.getSharedPreferences("project_dark_f5m_v1",0).edit().clear().commit();F5mSaveStore.install(c);GameView v=new GameView(c);v.layout(0,0,960,540);RuntimeState s=TownInteriorTest.field(v,"state");s.rpg().restoreGold(1000000);TownInteriorTest.enter(v,d);WorldRuntimeAdapter a=TownInteriorTest.field(v,"reagentShopAdapter");s.player().x=d.customerX();s.player().y=d.customerY();a.snapCameraToPlayer();shot(v,d.mapId+"-scene");WorldCameraTransform.Point target=a.worldToScreen(d.npcX(),d.npcY());TownInteriorTest.tap(v,target.x,target.y-24);TownShopWindow window=TownInteriorTest.field(v,"townWindow");
   if(d.kind==TownInteriorDef.Kind.INN){TownInteriorTest.tick(v,400);assertTrue(d.mapId,(Boolean)TownInteriorTest.field(v,"innDialogueOpen"));continue;}
   assertTrue(d.mapId,window.isOpen());if(d.kind!=TownInteriorDef.Kind.REAGENT&&d.kind!=TownInteriorDef.Kind.EQUIPMENT)continue;retail++;shot(v,d.mapId+"-shop");Method rows=TownShopWindow.class.getDeclaredMethod("rows");rows.setAccessible(true);@SuppressWarnings("unchecked") List<TownCommerce.Offer> offers=(List<TownCommerce.Offer>)rows.invoke(window);TownCommerce.Offer first=offers.get(0);long money=s.rpg().gold(),price=first.price;int owned=s.rpg().inventory().getOrDefault(first.id,0);
   TownInteriorTest.tap(v,120+270*1.125f,150*1.125f);shot(v,d.mapId+"-tooltip");TownInteriorTest.tap(v,120+570*1.125f,335*1.125f);assertEquals(money,s.rpg().gold().longValue());shot(v,d.mapId+"-confirm");TownInteriorTest.tap(v,120+490*1.125f,290*1.125f);assertEquals(d.mapId,money-price,s.rpg().gold().longValue());assertEquals(owned+1,s.rpg().inventory().get(first.id).intValue());
   // Every retail scene uses the same transactional rollback and sale paths, not image-only fixtures.
   window.guide(first.id,false);tap(window,570,335,()->false);tap(window,490,290,()->false);assertEquals(money-price,s.rpg().gold().longValue());assertEquals(owned+1,s.rpg().inventory().get(first.id).intValue());window.guide(first.id,true);long sell=TownCommerce.sellPrice(d,s,first.id);tap(window,570,335,()->F5mSaveStore.checkpointActive());tap(window,490,290,()->F5mSaveStore.checkpointActive());assertEquals(money-price+sell,s.rpg().gold().longValue());assertEquals(owned,s.rpg().inventory().getOrDefault(first.id,0).intValue());
   window.guide(first.id,false);tap(window,570,335,()->true);tap(window,480,210,()->true);assertEquals(2,((Integer)TownInteriorTest.field(window,"quantity")).intValue());tap(window,290,210,()->true);assertEquals(1,((Integer)TownInteriorTest.field(window,"quantity")).intValue());tap(window,320,290,()->true);assertFalse((Boolean)TownInteriorTest.field(window,"confirm"));tap(window,520,460,()->true);tap(window,350,320,()->true);assertEquals(1,((Integer)TownInteriorTest.field(window,"tab")).intValue());shot(v,d.mapId+"-sell");
   tap(window,580,460,()->true);assertFalse(window.isOpen());v.pause();F5mSaveStore.install(c);GameView restored=new GameView(c);RuntimeState rs=TownInteriorTest.field(restored,"state");assertEquals(d.mapId,rs.currentMapId());assertEquals(money-price+sell,rs.rpg().gold().longValue());
  }assertEquals(9,retail);
 }
 @Test public void bothCoastalLobbiesHaveNoYellowGateHaloAndRetainPortalPixels()throws Exception{
  for(String id:new String[]{AbelCoastGeometry.ENTRY,RucesionCoastGeometry.ENTRY}){GameView v=new GameView(c);v.layout(0,0,960,540);RuntimeState s=TownInteriorTest.field(v,"state");Method enter=GameView.class.getDeclaredMethod("changeCampaignMap",String.class,boolean.class);enter.setAccessible(true);enter.invoke(v,id,false);assertEquals(id,s.currentMapId());WorldMoveTargetController.TileCenter gate=CampaignWorld.forward(id);Bitmap b=Bitmap.createBitmap(192,128,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.translate(96-gate.x,64-gate.y);Method draw=GameView.class.getDeclaredMethod("drawCampaignGates",Canvas.class);draw.setAccessible(true);draw.invoke(v,canvas);int halo=0,visible=0;for(int color:px(b)){if(color==0xffffda72)halo++;if(Color.alpha(color)>0)visible++;}assertEquals(id,0,halo);assertTrue(id,visible>30);save(b,id+"-gate");b.recycle();WorldRuntimeAdapter a=TownInteriorTest.field(v,"poteFieldAdapter");s.player().x=gate.x-128;s.player().y=gate.y+64;a.snapCameraToPlayer();shot(v,id+"-lobby");}
 }
}
